                    briefingKey: 'r3_briefing',
                    d1: { labelKey: 'r3_d1_label', options: [
                        { value: 1, key: 'r3_d1_opt1' },
                        { value: 2, key: 'r3_d1_opt2' },
                        { value: 3, key: 'r3_d1_opt3' }
                    ]},
                    d2: { labelKey: 'r3_d2_label', options: [
                        { value: 3, key: 'r3_d2_opt3' },
                        { value: 2, key: 'r3_d2_opt2' },
                        { value: 1, key: 'r3_d2_opt1' }
                    ]},
                    d3: { labelKey: 'r3_d3_label', options: [
                        { value: 1, key: 'r3_d3_opt1' },
                        { value: 2, key: 'r3_d3_opt2' }
                    ]},
                    d4: { labelKey: 'r3_d4_label', hintKey: 'r3_d4_hint', min: 0, max: 15, def: 7 }
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_briefing',
                    d1: { labelKey: 'r4_d1_label', options: [
                        { value: 3, key: 'r4_d1_opt3' },
                        { value: 1, key: 'r4_d1_opt1' },
                        { value: 2, key: 'r4_d1_opt2' }
                    ]},
                    d2: { labelKey: 'r4_d2_label', options: [
                        { value: 2, key: 'r4_d2_opt2' },
                        { value: 3, key: 'r4_d2_opt3' },
                        { value: 1, key: 'r4_d2_opt1' }
                    ]},
                    d3: { labelKey: 'r4_d3_label', options: [
                        { value: 2, key: 'r4_d3_opt2' },
                        { value: 1, key: 'r4_d3_opt1' }
                    ]},
                    d4: { labelKey: 'r4_d4_label', hintKey: 'r4_d4_hint', min: 0, max: 100, def: 50 }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ceiling: CEILING,
                    budgetUsed: BASE_PAYROLL,   // running labour cost against £142m
                    retention: 100,             // % of critical master machinists retained
                    cliffExposure: 31000000,    // £ revenue still at risk from unmanaged exits
                    reskillROI: 0,              // x multiple (avoided cost / programme cost)
                    productivity: 100,          // age-diversity productivity index
                    stageMapQuality: 0,         // 0-100 quality of R1 segmentation
                    reskillFunded: 0,           // £ committed to reskilling
                    reskillHorizonOK: false,    // chose a multi-year horizon
                    phasedEnrolled: 0,          // # of the critical 15 enrolled in phased retirement
                    rewardDecoupled: false,     // pay re-anchored to contribution
                    transferMechanism: false,   // knowledge-transfer overlap built in
                    auditReady: false,
                    score: 0,
                    // history arrays for the chart
                    retentionHistory: [],
                    cliffHistory: [],
                    productivityHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { choiceA: 1, choiceB: 1, choiceC: 1, sliderD: 50 };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            // Briefing text + labels refresh on every call (no side effect on input values),
            // so a language switch mid-round is reflected immediately.
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var labelMap = [
                { labelId: 'decision1Label', config: round.d1 },
                { labelId: 'decision2Label', config: round.d2 },
                { labelId: 'decision3Label', config: round.d3 }
            ];
            labelMap.forEach(function(item) {
                var lbl = document.getElementById(item.labelId);
                if (lbl) lbl.textContent = t(item.config.labelKey);
            });
            var lbl4 = document.getElementById('decision4Label');
            if (lbl4) lbl4.textContent = t(round.d4.labelKey);
            var hint4 = document.getElementById('decision4Hint');
            if (hint4) hint4.textContent = t(round.d4.hintKey);

            // Option lists + the numeric default are only (re)populated when the rendered round
            // actually changes. This keeps the call idempotent: re-invoking it inside
            // validateDecisions must NOT wipe the player's current selections/entry before they
            // are read. Re-populating per round also re-translates the option labels.
            if (this._renderedPeriod === idx) return;
            this._renderedPeriod = idx;

            var selects = [
                { selectId: 'choiceA', config: round.d1 },
                { selectId: 'choiceB', config: round.d2 },
                { selectId: 'choiceC', config: round.d3 }
            ];
            selects.forEach(function(item) {
                var sel = document.getElementById(item.selectId);
                if (sel) {
                    sel.innerHTML = '';
                    item.config.options.forEach(function(opt) {
                        var o = document.createElement('option');
                        o.value = opt.value;
                        o.textContent = t(opt.key);
                        sel.appendChild(o);
                    });
                }
            });
            var num4 = document.getElementById('sliderD');
            if (num4) {
                num4.min = round.d4.min;
                num4.max = round.d4.max;
                num4.value = round.d4.def;
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var selA = document.getElementById('choiceA');
            if (selA) decisions.choiceA = parseInt(selA.value, 10);
            var selB = document.getElementById('choiceB');
            if (selB) decisions.choiceB = parseInt(selB.value, 10);
            var selC = document.getElementById('choiceC');
            if (selC) decisions.choiceC = parseInt(selC.value, 10);
            var numD = document.getElementById('sliderD');
            if (numD) decisions.sliderD = parseFloat(numD.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var bounds = this.ROUNDS[idx].d4;

            if (!Number.isFinite(decisions.sliderD) || decisions.sliderD < bounds.min || decisions.sliderD > bounds.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('range_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundCost = 0;
            var roundScore = 0;
            var eventSummary = '';

            if (period === 1) {
                // ROUND 1 — Map the multi-stage workforce.
                // choiceA: planning unit (1=headcount thinking [trap], 2=age bands, 3=life-stage + contribution)
                // choiceB: critical-skill mapping (1=none, 2=top lines only, 3=full tacit-skill inventory)
                // choiceC: data depth (1=HR headcount file, 2=skills matrix, 3=stage + retirement projection)
                // sliderD: % of effort spent on the 55+ critical cohort vs. spread thin

                var unitQuality = [0, 25, 60, 95][d.choiceA];          // headcount thinking scores low
                var skillMap = [0, 20, 60, 95][d.choiceB];
                var dataDepth = [0, 30, 65, 95][d.choiceC];
                // Focusing effort on the critical cohort sharpens the map; spreading thin dilutes it.
                var focusBonus = (d.sliderD - 50) * 0.25;

                ds.stageMapQuality = Math.max(0, Math.min(100, Math.round(
                    unitQuality * 0.45 + skillMap * 0.30 + dataDepth * 0.25 + focusBonus
                )));

                // Mapping is diagnostic, not yet a spend — minor consultancy cost.
                roundCost = 250000 + (d.choiceC === 3 ? 200000 : d.choiceC === 2 ? 90000 : 20000);
                ds.budgetUsed += roundCost;

                // A good map slightly de-risks the cliff (you now know where the 15 are);
                // headcount thinking leaves you blind.
                var cliffSeen = Math.round(ds.stageMapQuality * 30000);  // up to ~£2.85m visibility
                ds.cliffExposure = Math.max(0, 31000000 - cliffSeen);

                // Productivity barely moves yet, but headcount thinking misallocates and dents it.
                if (d.choiceA === 1) {
                    ds.productivity = Math.round(ds.productivity - 4);
                    eventSummary = window.mySimulation.t('event_headcount');
                }

                roundScore = Math.round(ds.stageMapQuality);

            } else if (period === 2) {
                // ROUND 2 — Fund the reskilling programme.
                // choiceA: programme design (1=light upskilling, 2=multi-skill conversion, 3=mentor-track conversion)
                // choiceB: time horizon used to justify spend (1=this year only [trap], 2=3-yr, 3=5-yr)
                // choiceC: offsetting cut (1=defer maintenance/overtime, 2=trim tenure-based increments, 3=cut external agency hires)
                // sliderD: programme spend in £m (0-9), drawn from the ceiling

                var spend = d.sliderD * 1000000;
                ds.reskillFunded = spend;
                roundCost = spend;
                ds.budgetUsed += roundCost;

                // Offsetting cut recovers some budget (the concept demands "offsetting cuts elsewhere").
                var offset = [0, 0.30, 0.55, 0.75][d.choiceC] * spend;
                ds.budgetUsed -= offset;

                ds.reskillHorizonOK = (d.choiceB >= 2);

                // Avoided cost over the chosen horizon: disruption avoided + fewer external hires + retained tacit knowledge.
                // Design quality and horizon both scale the return; a 1-year view massively understates it.
                var designMult = [0, 0.6, 1.0, 1.25][d.choiceA];
                var horizonMult = [0, 0.35, 1.0, 1.4][d.choiceB];   // 1-yr view ~ kills the case
                var avoidedCost = spend * 2.4 * designMult * horizonMult;

                ds.reskillROI = spend > 0 ? Math.round((avoidedCost / spend) * 10) / 10 : 0;

                // Reskilling widens the pipeline and converts operators to mentors → cuts cliff exposure.
                var cliffCut = Math.round(spend * 1.6 * designMult);
                ds.cliffExposure = Math.max(0, ds.cliffExposure - cliffCut);

                // Multi-skilling lifts age-diversity productivity; mentor-track design lifts it most.
                ds.productivity = Math.min(140, Math.round(ds.productivity + [0, 3, 7, 11][d.choiceA] * (ds.reskillHorizonOK ? 1 : 0.4)));

                // TRAP: short-horizon budgeting — cut the programme to protect this year.
                if (spend < 6000000) {
                    ds.cliffExposure = Math.min(31000000, ds.cliffExposure + 7000000);
                    ds.retention = Math.max(0, ds.retention - 8);
                    eventSummary = window.mySimulation.t('event_shorthorizon');
                } else if (!ds.reskillHorizonOK) {
                    eventSummary = window.mySimulation.t('event_horizonview');
                }

                // Score rewards a funded programme justified on a real horizon with a credible offset.
                roundScore = Math.round(
                    Math.min(100, ds.reskillROI / 3.5 * 100) * 0.45 +
                    (spend >= 6000000 ? 30 : spend / 6000000 * 30) +
                    [0, 8, 16, 25][d.choiceC]
                );

            } else if (period === 3) {
                // ROUND 3 — Set the phased-retirement policy.
                // choiceA: generosity of terms (1=stingy, 2=balanced, 3=very generous [budget trap])
                // choiceB: knowledge-transfer mechanism (1=none, 2=informal handover, 3=structured mentoring overlap)
                // choiceC: reward basis (1=keep tenure-based pay [trap], 2=decouple — re-anchor to contribution)
                // sliderD: how many of the critical 15 to enrol (0-15)

                var enrolled = Math.round(d.sliderD);
                ds.phasedEnrolled = enrolled;
                ds.rewardDecoupled = (d.choiceC === 2);
                ds.transferMechanism = (d.choiceB === 3);

                // Cost of the scheme. Generous terms cost more per head; tenure-based pay means
                // a part-time mentor still draws near a full-time salary (the un-fundable trap).
                var perHeadFull = 95000;       // full-time senior machinist cost
                var partFraction = [0, 0.45, 0.60, 0.80][d.choiceA];  // generosity = more salary retained
                // If reward stays tenure-based, you cannot taper pay with the role → cost barely drops.
                var tenurePenalty = ds.rewardDecoupled ? 1.0 : 1.45;
                var schemeCostPerHead = perHeadFull * partFraction * tenurePenalty;
                // Phased retirees move OFF full-time payroll, so net cost = scheme cost (their old full salary leaves the run-rate).
                roundCost = Math.round(enrolled * schemeCostPerHead);
                ds.budgetUsed += roundCost;

                // Tacit-knowledge retention is the share of the critical 15 actively held by the
                // phased scheme. Anyone NOT enrolled drifts toward full retirement and is lost,
                // so retention is anchored to enrolment quality — it does not stay at 100 for free.
                var transferQuality = [0, 0.25, 0.55, 1.0][d.choiceB];
                var enrolFrac = enrolled / 15;
                var capturedFrac = enrolFrac * (0.45 + 0.55 * transferQuality);
                ds.retention = Math.round(Math.min(100, 100 * capturedFrac + 8));

                // Cliff exposure falls as enrolled + transfer mechanism capture the tacit knowledge.
                var cliffCut3 = Math.round(enrolFrac * 14000000 * (0.3 + 0.7 * transferQuality));
                ds.cliffExposure = Math.max(0, ds.cliffExposure - cliffCut3);

                // Age-diversity productivity rises when experienced mentors pair with younger operators.
                ds.productivity = Math.min(150, Math.round(ds.productivity + enrolFrac * 14 * transferQuality + (ds.rewardDecoupled ? 4 : 0)));

                // TRAP: too stingy → master machinists just fully retire, taking knowledge with them.
                if (d.choiceA === 1 && enrolled < 10) {
                    var walked = Math.max(0, 6 - Math.round(enrolled / 2));
                    ds.retention = Math.max(0, ds.retention - walked * 8);
                    ds.cliffExposure = Math.min(31000000, ds.cliffExposure + walked * 2500000);
                    ds.productivity = Math.round(ds.productivity - walked * 2);
                    eventSummary = window.mySimulation.t('event_walkout');
                } else if (!ds.transferMechanism && enrolled > 0) {
                    // Enrolled but no real transfer mechanism — knowledge still erodes.
                    ds.cliffExposure = Math.min(31000000, ds.cliffExposure + 3500000);
                    eventSummary = window.mySimulation.t('event_notransfer');
                } else if (enrolled === 15) {
                    // Everyone enrolled: the round score below gives 8 instead of 15, and the composite charges the same 7.
                    eventSummary = window.mySimulation.t('event_allenrolled');
                }

                roundScore = Math.round(
                    (ds.retention / 100) * 35 +
                    transferQuality * 30 +
                    (ds.rewardDecoupled ? 20 : 0) +
                    (enrolled >= 10 && enrolled <= 14 ? 15 : enrolled === 15 ? 8 : 5)
                );

            } else if (period === 4) {
                // ROUND 4 — Defend the integrated three-stage strategy.
                // choiceA: how to close any remaining budget gap (1=ignore ceiling [trap], 2=trim tenure increments, 3=convert remaining roles to multi-stage)
                // choiceB: audit narrative (1=cost-cutting story, 2=capability-continuity story, 3=integrated multi-stage story)
                // choiceC: final reward stance (1=revert to tenure under pressure, 2=hold the decoupled line)
                // sliderD: % of remaining flex applied to the knowledge-transfer overlap for the aerospace lines

                // Integration savings: a coherent multi-stage model funds itself only if reward is decoupled.
                var integrate = [0, 0, 0.55, 0.85][d.choiceA];
                var holdLine = (d.choiceC === 2) && ds.rewardDecoupled;
                var savings = Math.round(BASE_PAYROLL * 0.018 * integrate * (holdLine ? 1.0 : 0.45));
                ds.budgetUsed -= savings;
                if (d.choiceC === 1) ds.rewardDecoupled = false;

                // Final transfer push for the aerospace lines.
                var transferPush = d.sliderD / 100;
                var pushCost = Math.round(1500000 * transferPush);
                roundCost = pushCost;
                ds.budgetUsed += pushCost;

                ds.cliffExposure = Math.max(0, Math.round(ds.cliffExposure * (1 - 0.6 * transferPush * (ds.transferMechanism ? 1 : 0.4))));
                ds.retention = Math.min(100, Math.round(ds.retention + transferPush * 8 * (ds.transferMechanism ? 1 : 0.5)));
                ds.productivity = Math.min(155, Math.round(ds.productivity + (d.choiceB === 3 ? 6 : d.choiceB === 2 ? 3 : 0)));

                // Audit readiness: a credible knowledge-transfer plan + low cliff + capability narrative.
                var overBudget = Math.max(0, ds.budgetUsed - CEILING);
                ds.auditReady = (ds.cliffExposure <= 12000000) && ds.transferMechanism && (overBudget === 0) && (d.choiceB >= 2);

                // TRAP: ignore the ceiling.
                if (d.choiceA === 1 && ds.budgetUsed > CEILING) {
                    eventSummary = window.mySimulation.t('event_overbudget');
                }
                if (ds.auditReady) {
                    eventSummary = window.mySimulation.t('event_auditpass');
                } else if (ds.cliffExposure > 12000000) {
                    eventSummary = window.mySimulation.t('event_auditrisk');
                }

                var overPenalty = Math.min(45, Math.round(overBudget / 1000000 * 5));
                roundScore = Math.round(
                    (ds.retention / 100) * 25 +
                    (Math.max(0, 31000000 - ds.cliffExposure) / 31000000) * 25 +
                    (Math.min(150, ds.productivity) / 150) * 20 +
                    (ds.auditReady ? 20 : 0) +
                    (holdLine ? 10 : 0) -
                    overPenalty
                );
                roundScore = Math.max(0, roundScore);
            }

            ds.score = roundScore;

            ds.retentionHistory.push(Math.round(ds.retention));
            ds.cliffHistory.push(Math.round(ds.cliffExposure / 1000000 * 10) / 10);
            ds.productivityHistory.push(Math.round(ds.productivity));
            ds.scoreHistory.push(roundScore);

            var results = {
                period: period,
                roundScore: roundScore,
                budgetUsed: ds.budgetUsed,
                overBudget: Math.max(0, ds.budgetUsed - CEILING),
                retention: Math.round(ds.retention),
                cliffExposure: ds.cliffExposure,
                reskillROI: ds.reskillROI,
                productivity: Math.round(ds.productivity),
                phasedEnrolled: ds.phasedEnrolled,
                roundCost: roundCost,
                eventSummary: eventSummary
            };

            // Running instructor score every round: the composite the final debrief uses, from this round.
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, this._composite(results))) });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        // Composite multi-stage-strategy score from one round of results.
        // Cliff-closed only counts the share actually defused; productivity scored above the
        // 100 baseline so doing nothing earns about 0; budget discipline collapses on a breach.
        _composite(r) {
            r = r || {};
            var finalRetention = r.retention != null ? r.retention : 100;
            var finalCliff = r.cliffExposure != null ? r.cliffExposure : 31000000;
            var finalProductivity = r.productivity != null ? r.productivity : 100;
            var finalROI = r.reskillROI != null ? r.reskillROI : 0;
            var overBudget = r.overBudget != null ? r.overBudget : 0;
            var cliffClosed = Math.max(0, (31000000 - finalCliff) / 31000000) * 100;
            var prodGain = Math.max(0, Math.min(100, (finalProductivity - 100) / 50 * 100));
            var roiScore = Math.max(0, Math.min(100, finalROI / 3.5 * 100));
            var budgetDiscipline = overBudget > 0 ? Math.max(0, 100 - (overBudget / 1000000) * 18) : 100;
            // Enrolling all 15 costs what the Round 3 score charges for it: 8 points instead of 15, so 7 off.
            var enrolCost = r.phasedEnrolled === 15 ? 7 : 0;
            return Math.max(0, Math.round(
                Math.min(100, finalRetention) * 0.28 +
                cliffClosed * 0.26 +
                prodGain * 0.16 +
                roiScore * 0.14 +
                budgetDiscipline * 0.16
            ) - enrolCost);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budgetUsed', function(v) { return gbpM(v); });
            uiManager.bind('retentionDisplay', 'domainState.retention', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('cliffDisplay', 'domainState.cliffExposure', function(v) { return gbpM(v); });
            uiManager.bind('roiDisplay', 'domainState.reskillROI', function(v) {
                return v > 0 ? (Math.round(v * 10) / 10) + 'x' : '—';
            });
            uiManager.bind('productivityDisplay', 'domainState.productivity', function(v) { return Math.round(v); });
            uiManager.bind('scoreDisplay', 'domainState.score', function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Talent Retention (%)',
                                data: [],
                                borderColor: '#4fb286',
                                backgroundColor: 'rgba(79,178,134,0.12)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Age-Diversity Productivity',
                                data: [],
                                borderColor: '#b083d4',
                                backgroundColor: 'rgba(176,131,212,0.05)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Knowledge-Cliff Exposure (£m)',
