        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) {
                return (window.mySimulation ? window.mySimulation.t('round_short') : 'R') + (i + 1);
            });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.retentionHistory },
                        { data: state.domainState.productivityHistory },
                        { data: state.domainState.cliffHistory }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.retention', label: 'Retention', i18nKey: 'col_retention', formatter: function(v) { return Math.round(v) + '%'; } },
                { key: 'results.cliffExposure', label: 'Cliff', i18nKey: 'col_cliff', formatter: function(v) { return gbpM(v); } },
                { key: 'results.reskillROI', label: 'ROI', i18nKey: 'col_roi', formatter: function(v) { return v > 0 ? (Math.round(v * 10) / 10) + 'x' : '—'; } },
                { key: 'results.budgetUsed', label: 'Labour Cost', i18nKey: 'col_budget', formatter: function(v) { return gbpM(v); } }
            ];
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.eventSummary) return results.eventSummary;
            var ds = state.domainState;
            if (results.overBudget > 0) return window.mySimulation.t('hint_overbudget');
            if (ds.cliffExposure > 20000000) return window.mySimulation.t('hint_cliff');
            if (state.currentPeriod === 2 && !ds.reskillHorizonOK) return window.mySimulation.t('hint_horizon');
            if (state.currentPeriod === 3 && !ds.rewardDecoupled) return window.mySimulation.t('hint_decouple');
            if (state.currentPeriod === 4) return window.mySimulation.t('hint_audit');
            return null;
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var c = summary.compositeScore != null ? summary.compositeScore : 0;
            var gk = c > 78 ? 'grade_excellent' : c > 62 ? 'grade_good' : c > 45 ? 'grade_developing' : 'grade_needs';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="ll-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var gbp = function (v) { return '\u00a3' + (Math.round((v || 0) / 100000) / 10) + 'm'; };
            var metrics = ''
                + metric(t('comp_retention_label'), (summary.talentRetention != null ? summary.talentRetention : '-') + '%')
                + metric(t('comp_cliff_label'), (summary.knowledgeCliffClosed != null ? summary.knowledgeCliffClosed : '-') + '%')
                + metric(t('comp_prod_label'), (summary.ageDiversityProductivity != null ? summary.ageDiversityProductivity : '-'))
                + metric(t('comp_roi_label'), (summary.reskillROI != null ? summary.reskillROI : '-') + 'x')
                + metric(t('comp_budget_label'), (summary.budgetDiscipline != null ? summary.budgetDiscipline : '-'))
                + metric(t('comp_cost_label'), gbp(summary.labourCost));
            return ''
                + '<div class="ll-completion">'
                +   '<div class="ll-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="ll-completion-verdict">' + t(gk) + '</div>'
                +   '<div class="ll-completion-score">' + t('comp_score_label') + ': <strong>' + Math.round(c) + '</strong> / 100</div>'
                +   '<div class="ll-completion-metrics">' + metrics + '</div>'
                +   (items ? '<div class="ll-completion-insights-heading">' + t('comp_insights_heading') + '</div><ul class="ll-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var totalScore = history.reduce(function(s, h) {
                return s + (h.results ? (h.results.roundScore || 0) : 0);
            }, 0);
            var avgScore = Math.round(totalScore / history.length);

            var finalRetention = r.retention != null ? r.retention : 100;
            var finalCliff = r.cliffExposure != null ? r.cliffExposure : 31000000;
            var finalProductivity = r.productivity != null ? r.productivity : 100;
            var finalROI = r.reskillROI != null ? r.reskillROI : 0;
            var overBudget = r.overBudget != null ? r.overBudget : 0;
            var budgetUsed = r.budgetUsed != null ? r.budgetUsed : BASE_PAYROLL;

            // Composite multi-stage-strategy score: one method, also written every round (_composite).
            // The parts stay here too, because the summary reports them.
            var cliffClosed = Math.max(0, (31000000 - finalCliff) / 31000000) * 100;
            var prodGain = Math.max(0, Math.min(100, (finalProductivity - 100) / 50 * 100));
            var roiScore = Math.max(0, Math.min(100, finalROI / 3.5 * 100));
            var budgetDiscipline = overBudget > 0 ? Math.max(0, 100 - (overBudget / 1000000) * 18) : 100;
            var composite = this._composite(r);

            var performance = 'Needs Improvement';
            if (composite > 78) performance = 'Excellent';
            else if (composite > 62) performance = 'Good';
            else if (composite > 45) performance = 'Developing';

            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var insights = [];
            if (overBudget > 0) insights.push(t('insight_overbudget'));
            if (finalCliff > 12000000) insights.push(t('insight_cliff'));
            if (finalROI < 2) insights.push(t('insight_roi'));
            if (finalRetention < 80) insights.push(t('insight_retention'));
            if (finalProductivity < 105) insights.push(t('insight_productivity'));
            if (r.phasedEnrolled === 15) insights.push(t('insight_allenrolled'));
            if (composite > 65 && overBudget === 0) insights.push(t('insight_strong'));
            if (insights.length === 0) insights.push(t('insight_default'));

            // v1.1.0 FIX — surface the weighted COMPOSITE as the final instructor score
            // (express_resolveDomainScore reads performance.overallScore / domainState.score).
            // Per-round ds.score (roundScore) is untouched so the score-trend is unchanged.
            var _gk = composite > 78 ? 'grade_excellent' : composite > 62 ? 'grade_good' : composite > 45 ? 'grade_developing' : 'grade_needs';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = composite;
                window.mySimulation.state.domainState.performance = { overallScore: composite, grade: t(_gk) };
            }
            return {
                totalScore: totalScore,
                averageScore: avgScore,
                compositeScore: composite,
                talentRetention: Math.round(finalRetention),
                knowledgeCliffClosed: Math.round(cliffClosed),
                ageDiversityProductivity: Math.round(finalProductivity),
                reskillROI: finalROI,
                budgetDiscipline: Math.round(budgetDiscipline),
                labourCost: Math.round(budgetUsed),
                performance: performance,
                insights: insights
            };
        }

